mapper.select:
select cc.id, cc.coupon_id, cc.customer_id, cc.status, cc.create_time, cc.use_time_start, cc.use_time_end, c.name, c.type, c.threshold_amount, c.deduction_amount, c.receive_num, c.receive_time_start, c.receive_time_end, c.receive_type, c.count, c.range_type, c.sort, c.coupon_remark from sys_customer_coupon cc join sys_coupon c on cc.coupon_id = c.id
and cc.status = 1
and cc.id = #{id}
and cc.coupon_id = #{couponId}
and cc.customer_id = #{customerId}
and cc.coupon_id in
#{couponId}
and (
( c.range_type = ${k} and c.threshold_amount <= ${priceMap[k]} )
)
and cc.use_time_start <= now() and cc.use_time_end > now()
order by c.sort, cc.create_time desc
